using System;using System.Collections.Generic;using System.IO;using UnityEngine;using Exoduser.UnityPort.Core;
namespace Exoduser.UnityPort {
 public sealed partial class NativeGame {
  [Serializable] sealed class ParryFeedbackData {public ParryFeedbackTuning standard=new ParryFeedbackTuning(),pushIn=new ParryFeedbackTuning{meleeShake=2,projectileShake=4,meleeCameraPushIn=.08f};}
  sealed class MeleeMarker {public SpriteRenderer core,halo;public LineRenderer ring,path;public TextMesh label;}
  readonly Dictionary<int,MeleeMarker> meleeMarkers=new Dictionary<int,MeleeMarker>();
  readonly Dictionary<Transform,Tuple<Vector3,Vector3>> meleePoses=new Dictionary<Transform,Tuple<Vector3,Vector3>>();
  static readonly HashSet<SpriteRenderer> meleeSprites=new HashSet<SpriteRenderer>();
  readonly ParryRhythmBot g2ParryBot=new ParryRhythmBot();
  Sprite meleeWhite;Material meleeMaterial;float parryHoldUntil;int statsDeathSeen=-1;bool statsClearSeen;
  void ConfigureParryFeedback(){var raw=Resources.Load<TextAsset>("Data/parry_feedback");var data=raw!=null?JsonUtility.FromJson<ParryFeedbackData>(raw.text):new ParryFeedbackData();Simulation.ParryFeedback=Array.IndexOf(Environment.GetCommandLineArgs(),"--parry-feedback-push-in")>=0?data.pushIn:data.standard;statsDeathSeen=0;statsClearSeen=false;}
  void RestoreMeleePoses(){foreach(var p in meleePoses)if(p.Key!=null){p.Key.position=p.Value.Item1;p.Key.localScale=p.Value.Item2;}meleePoses.Clear();}
  SpriteRenderer MeleeLine(string name){if(meleeWhite==null)meleeWhite=Sprite.Create(Texture2D.whiteTexture,new Rect(0,0,1,1),new Vector2(.5f,.5f),100);var r=CreateRenderer(name);r.sprite=meleeWhite;r.sortingOrder=30000;meleeSprites.Add(r);return r;}
  MeleeMarker Marker(int id){if(meleeMarkers.TryGetValue(id,out var m))return m;m=new MeleeMarker{core=MeleeLine("Melee glint "+id),halo=MeleeLine("Melee halo "+id)};m.halo.sortingOrder=29999;
   var go=new GameObject("Melee DANGER "+id);go.transform.SetParent(transform,false);m.ring=go.AddComponent<LineRenderer>();if(meleeMaterial==null)meleeMaterial=new Material(Shader.Find("Sprites/Default"));m.ring.sharedMaterial=meleeMaterial;m.ring.loop=true;m.ring.positionCount=32;m.ring.widthMultiplier=.035f;m.ring.sortingOrder=30000;
   var pathGo=new GameObject("DANGER charge path");pathGo.transform.SetParent(go.transform,false);m.path=pathGo.AddComponent<LineRenderer>();m.path.sharedMaterial=meleeMaterial;m.path.positionCount=2;m.path.widthMultiplier=.09f;m.path.sortingOrder=30000;
   var text=new GameObject("DANGER");text.transform.SetParent(go.transform,false);m.label=text.AddComponent<TextMesh>();m.label.text="DANGER";m.label.font=font;m.label.fontSize=36;m.label.characterSize=.035f;m.label.anchor=TextAnchor.MiddleCenter;var mr=text.GetComponent<MeshRenderer>();mr.sortingOrder=30001;if(font!=null)mr.sharedMaterial=font.material;meleeMarkers[id]=m;return m;}
  static float PixelsPerWorld(Camera camera,Vector3 at){return Mathf.Max(1,Vector3.Distance(camera.WorldToScreenPoint(at),camera.WorldToScreenPoint(at+camera.transform.right)));}
  void ApplyMeleePresentation(Camera camera){if(camera==null||Simulation==null)return;
   foreach(var e in Simulation.Enemies){if(!e.Alive||e.IsBoss||e.Web==null)continue;var w=e.Web;bool telling=w.s=="g2Tell",active=w.s=="g2Active";int age=Simulation.TickCount-e.MeleeParriedTick;bool spark=age>=2&&age<=6;bool glint=telling&&!w.MeleeUnparryable&&w.MeleeTellMax-w.MeleeTimer>=2&&w.MeleeTellMax-w.MeleeTimer<11;
    if(enemies.TryGetValue(e.Id,out var ev)&&(telling||active||age>=6&&Simulation.TickCount<e.MeleeFreezeUntil))foreach(var sr in new[]{ev.body,ev.walk}){if(sr==null||sr.sprite==null)continue;var tr=sr.transform;if(!meleePoses.ContainsKey(tr))meleePoses[tr]=Tuple.Create(tr.position,tr.localScale);var screen=camera.WorldToScreenPoint(tr.position);var player=camera.WorldToScreenPoint(NativeRemodel3D.Point(Simulation.Player.X,Simulation.Player.Y));var dir=((Vector2)(player-screen)).normalized;float shift=telling?-6:active&&w.MeleeActiveMax-w.MeleeTimer<2?14:age>=6?-18:0;tr.position=camera.ScreenToWorldPoint(screen+new Vector3(dir.x,dir.y,0)*shift);if(telling)tr.localScale=Vector3.Scale(tr.localScale,new Vector3(1.06f,.94f,1));}
    if(!telling&&!active&&!spark&&!meleeMarkers.ContainsKey(e.Id))continue;var m=Marker(e.Id);m.core.enabled=m.halo.enabled=glint||spark;bool danger=telling&&w.MeleeUnparryable;m.ring.enabled=danger;m.path.enabled=danger&&w.MeleeSource=="charge";m.label.gameObject.SetActive(danger);
    var ground=NativeRemodel3D.Point(e.X,e.Y);var upper=ground+camera.transform.up*(e.Radius*.045f);float ppw=PixelsPerWorld(camera,upper);float length=Mathf.Max(28, e.Radius*7*.3f)/ppw;var targetScreen=camera.WorldToScreenPoint(NativeRemodel3D.Point(Simulation.Player.X,Simulation.Player.Y));var upperScreen=camera.WorldToScreenPoint(upper);float glintAngle=Mathf.Atan2(targetScreen.y-upperScreen.y,targetScreen.x-upperScreen.x)*Mathf.Rad2Deg;var rot=camera.transform.rotation*Quaternion.Euler(0,0,glintAngle);
    foreach(var sr in new[]{m.core,m.halo}){sr.transform.SetPositionAndRotation(upper,rot);sr.transform.localScale=new Vector3(length*100,sr==m.core?150/ppw:400/ppw,1);}
    m.core.color=new Color(.949f,.902f,.784f,spark?1-(age-2)/5f:1);m.halo.color=new Color(.643f,.576f,.451f,.45f);
    if(danger){float radius=(w.MeleeSource=="charge"?e.Radius+24:70+e.Radius)/100f;for(int k=0;k<32;k++){float a=k*Mathf.PI*2/32;m.ring.SetPosition(k,ground+(NativeRemodel3D.Active?new Vector3(Mathf.Cos(a)*radius,.03f,Mathf.Sin(a)*radius):new Vector3(Mathf.Cos(a)*radius,Mathf.Sin(a)*radius,0)));}m.ring.startColor=Color.HSVToRGB((Simulation.TickCount%60)/60f,.65f,1);m.ring.endColor=Color.HSVToRGB(((Simulation.TickCount+35)%60)/60f,.65f,1);if(m.path.enabled){float progress=Mathf.Clamp01(1-(float)(w.MeleeTimer/w.MeleeTellMax));float pathLength=(e.Radius+125)*progress;var end=NativeRemodel3D.Point(e.X+(float)w.echDx*pathLength,e.Y+(float)w.echDy*pathLength);m.path.SetPosition(0,ground);m.path.SetPosition(1,end);m.path.startColor=m.ring.startColor;m.path.endColor=m.ring.endColor;}m.label.color=m.ring.startColor;m.label.transform.SetPositionAndRotation(ground+camera.transform.up*.2f,camera.transform.rotation);}
   }
   var dead=new List<int>();foreach(var p in meleeMarkers){var e=Simulation.Enemies.Find(x=>x.Id==p.Key&&x.Alive);if(e==null)dead.Add(p.Key);}foreach(int id in dead){var m=meleeMarkers[id];meleeSprites.Remove(m.core);meleeSprites.Remove(m.halo);Destroy(m.core.gameObject);Destroy(m.halo.gameObject);Destroy(m.ring.gameObject);meleeMarkers.Remove(id);}
  }
  void ParryFeedbackEvent(FeedbackEvent e){if(e.Kind==FeedbackKind.Parry&&e.MeleeParry&&e.HitStopTicks>0)parryHoldUntil=Mathf.Max(parryHoldUntil,Time.unscaledTime+e.HitStopTicks/60f);}
  void WriteCombatStats(string output){if(Simulation==null||string.IsNullOrEmpty(output))return;Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"combat-stats.json"),Simulation.CombatStatsJson());}
  void ObserveCombatStatsEnd(){if(Simulation==null)return;if(Simulation.Stats.deaths>statsDeathSeen||Simulation.Stage.StageCleared&&!statsClearSeen){statsDeathSeen=Simulation.Stats.deaths;statsClearSeen=Simulation.Stage.StageCleared;var path=Argument("-output");if(string.IsNullOrEmpty(path))path=Path.Combine(Application.persistentDataPath,"combat-stats");WriteCombatStats(path);}}
 }
}
